import json
import csv
import logging
from pathlib import Path
from typing import List, Dict, Any, Optional

from config import get_path_config, get_evaluation_config
from utils.logger import get_logger

logger = get_logger(__name__)

def load_robustness_metrics(filepath: Optional[Path] = None) -> List[Dict[str, Any]]:
    """Load the robustness metrics CSV generated by T024."""
    path_config = get_path_config()
    if filepath is None:
        filepath = path_config.processed_dir / "robustness_metrics.csv"
    
    if not filepath.exists():
        raise FileNotFoundError(f"Robustness metrics file not found: {filepath}")
    
    metrics = []
    with open(filepath, 'r', newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            metrics.append({
                'model_id': row['model_id'],
                'auc': float(row['auc']),
                'latency_ms': float(row['latency_ms']),
                'ram_gb': float(row['ram_gb'])
            })
    return metrics

def extract_compression_metadata(model_id: str) -> Dict[str, Any]:
    """Extract bit-width and parameter count from model_id string.
    
    Expected model_id format: 'wav2vec2_{precision}_{pruning_ratio}'
    e.g., 'wav2vec2_int8_0.0', 'wav2vec2_fp32_0.2'
    """
    parts = model_id.split('_')
    if len(parts) < 3:
        logger.warning(f"Could not parse model_id: {model_id}, assuming default")
        return {'bit_width': 32, 'pruning_ratio': 0.0, 'param_count': 0}
    
    precision_part = parts[1]
    if precision_part.startswith('int'):
        bit_width = int(precision_part[3:])
    elif precision_part == 'fp32':
        bit_width = 32
    else:
        bit_width = 32  # Default fallback
    
    try:
        pruning_ratio = float(parts[2])
    except (ValueError, IndexError):
        pruning_ratio = 0.0
    
    return {
        'bit_width': bit_width,
        'pruning_ratio': pruning_ratio,
        'param_count': 0  # Would need to load model to get this, skipping for analysis
    }

def compute_correlation_data(metrics: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Compute correlation data points: bit-width vs AUC."""
    data_points = []
    
    for m in metrics:
        metadata = extract_compression_metadata(m['model_id'])
        data_points.append({
            'model_id': m['model_id'],
            'bit_width': metadata['bit_width'],
            'auc': m['auc'],
            'pruning_ratio': metadata['pruning_ratio']
        })
    
    # Sort by bit_width ascending (more compression -> lower bit-width)
    data_points.sort(key=lambda x: (x['bit_width'], x['pruning_ratio']))
    
    return data_points

def save_correlation_data(data: List[Dict[str, Any]], filepath: Optional[Path] = None) -> None:
    """Save correlation data to JSON."""
    path_config = get_path_config()
    if filepath is None:
        filepath = path_config.processed_dir / "correlation_data.json"
    
    filepath.parent.mkdir(parents=True, exist_ok=True)
    
    with open(filepath, 'w', encoding='utf-8') as f:
        json.dump(data, f, indent=2)
    
    logger.info(f"Saved correlation data to {filepath}")

def validate_correlation_data(data: List[Dict[str, Any]]) -> bool:
    """Validate correlation data has required fields and reasonable values."""
    if not data:
        logger.error("Correlation data is empty")
        return False
    
    required_keys = {'model_id', 'bit_width', 'auc'}
    for point in data:
        if not required_keys.issubset(point.keys()):
            logger.error(f"Missing keys in data point: {point}")
            return False
        if not 0.0 <= point['auc'] <= 1.0:
            logger.error(f"Invalid AUC value: {point['auc']}")
            return False
    
    return True

def detect_step_change(correlation_data: List[Dict[str, Any]], threshold: float = 0.10) -> Dict[str, Any]:
    """Detect the breaking point where relative AUC drop exceeds threshold.
    
    Args:
        correlation_data: List of data points sorted by bit_width ascending.
        threshold: Relative AUC drop threshold (default 10% = 0.10).
    
    Returns:
        Dict containing breaking point info.
    """
    if not correlation_data:
        raise ValueError("Correlation data is empty")
    
    # Sort by bit_width ascending (most compressed first)
    sorted_data = sorted(correlation_data, key=lambda x: (x['bit_width'], x['pruning_ratio']))
    
    # Find the baseline (highest bit-width, least compressed)
    baseline = sorted_data[-1]
    baseline_auc = baseline['auc']
    baseline_bit_width = baseline['bit_width']
    
    logger.info(f"Baseline AUC (bit-width {baseline_bit_width}): {baseline_auc:.4f}")
    
    breaking_point = None
    max_drop = 0.0
    
    # Iterate through points from most compressed to least
    for i, point in enumerate(sorted_data):
        if point['auc'] < baseline_auc:
            relative_drop = (baseline_auc - point['auc']) / baseline_auc
        else:
            relative_drop = 0.0
        
        if relative_drop > max_drop:
            max_drop = relative_drop
            breaking_point = {
                'model_id': point['model_id'],
                'bit_width': point['bit_width'],
                'auc': point['auc'],
                'baseline_auc': baseline_auc,
                'relative_drop': relative_drop,
                'threshold_violated': relative_drop > threshold
            }
        
        # If we found a violation, we can stop (first breaking point from most compressed)
        if relative_drop > threshold:
            break
    
    if breaking_point is None:
        # No violation found, use the last point as the "best" non-breaking point
        last_point = sorted_data[0]
        relative_drop = (baseline_auc - last_point['auc']) / baseline_auc if baseline_auc > 0 else 0.0
        breaking_point = {
            'model_id': last_point['model_id'],
            'bit_width': last_point['bit_width'],
            'auc': last_point['auc'],
            'baseline_auc': baseline_auc,
            'relative_drop': relative_drop,
            'threshold_violated': relative_drop > threshold
        }
    
    return breaking_point

def save_breaking_point(breaking_point: Dict[str, Any], filepath: Optional[Path] = None) -> None:
    """Save breaking point analysis to JSON."""
    path_config = get_path_config()
    if filepath is None:
        filepath = path_config.processed_dir / "breaking_point.json"
    
    filepath.parent.mkdir(parents=True, exist_ok=True)
    
    with open(filepath, 'w', encoding='utf-8') as f:
        json.dump(breaking_point, f, indent=2)
    
    logger.info(f"Saved breaking point analysis to {filepath}")
    logger.info(f"Threshold violated: {breaking_point['threshold_violated']}")
    logger.info(f"Max relative drop: {breaking_point['relative_drop']:.2%}")

def run_analysis(input_filepath: Optional[Path] = None, output_filepath: Optional[Path] = None) -> Dict[str, Any]:
    """Run the full robustness curve analysis pipeline.
    
    1. Load robustness metrics
    2. Compute correlation data
    3. Detect step change (breaking point)
    4. Save results
    
    Args:
        input_filepath: Path to robustness_metrics.csv (optional)
        output_filepath: Path to breaking_point.json (optional)
    
    Returns:
        Dict containing breaking point analysis results.
    """
    path_config = get_path_config()
    
    # Load metrics
    metrics = load_robustness_metrics(input_filepath)
    logger.info(f"Loaded {len(metrics)} metric records")
    
    # Compute correlation data
    correlation_data = compute_correlation_data(metrics)
    logger.info(f"Computed {len(correlation_data)} correlation data points")
    
    # Save correlation data (for T029 compliance)
    correlation_output = path_config.processed_dir / "correlation_data.json"
    save_correlation_data(correlation_data, correlation_output)
    
    # Validate
    if not validate_correlation_data(correlation_data):
        raise ValueError("Correlation data validation failed")
    
    # Detect breaking point
    eval_config = get_evaluation_config()
    threshold = eval_config.get('auc_drop_threshold', 0.10)
    breaking_point = detect_step_change(correlation_data, threshold=threshold)
    
    # Save breaking point
    save_breaking_point(breaking_point, output_filepath)
    
    return breaking_point

def main():
    """Entry point for robustness curve analysis."""
    logging.basicConfig(level=logging.INFO)
    
    try:
        result = run_analysis()
        logger.info("Analysis completed successfully")
        logger.info(f"Breaking point: {result}")
    except Exception as e:
        logger.error(f"Analysis failed: {e}", exc_info=True)
        raise

if __name__ == "__main__":
    main()